-- =========================================================================
-- NCERT Notes — shared (community) notes
-- Run this once in Supabase: Dashboard → SQL Editor → New query → Run.
-- Safe to run again. Needs schema.sql to have been run first.
--
-- One shared copy of notes per chapter that EVERY visitor can read, so a
-- chapter generated by one student never has to be generated again.
--   * Anyone (even signed out) can read visible shared notes.
--   * Only signed-in students can share, and only through
--     publish_shared_notes(), which checks the notes and never lets a
--     more complete copy be replaced by a less complete one.
--   * Who shared is never exposed; a first name is shown only if they opt in.
--   * 3 reports from different students hide a chapter automatically.
--     Review it in Table Editor → shared_notes (set hidden = false to restore,
--     or delete the row).
-- =========================================================================

create table if not exists public.shared_notes (
  chapter_id       text        primary key check (char_length(chapter_id) <= 120),
  outline          jsonb       not null,
  chunks           jsonb       not null,
  parts_done       int         not null,
  parts_total      int         not null,
  model            text,
  contributor_name text,                       -- first name, only if the sharer opted in
  contributed_by   uuid        references auth.users (id) on delete set null,
  report_count     int         not null default 0,
  hidden           boolean     not null default false,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

alter table public.shared_notes enable row level security;

drop policy if exists "Anyone can read visible shared notes" on public.shared_notes;
create policy "Anyone can read visible shared notes" on public.shared_notes
  for select to anon, authenticated using (not hidden);

-- Readers get every column except who shared it and the moderation fields.
revoke all on public.shared_notes from anon, authenticated;
grant select (chapter_id, outline, chunks, parts_done, parts_total, model, contributor_name, created_at, updated_at)
  on public.shared_notes to anon, authenticated;

-- ---------- reports ----------
create table if not exists public.shared_note_reports (
  chapter_id text        not null references public.shared_notes (chapter_id) on delete cascade,
  reporter   uuid        not null default auth.uid() references auth.users (id) on delete cascade,
  reason     text        check (char_length(reason) <= 500),
  created_at timestamptz not null default now(),
  primary key (chapter_id, reporter)
);

alter table public.shared_note_reports enable row level security;

drop policy if exists "Students file their own reports" on public.shared_note_reports;
create policy "Students file their own reports" on public.shared_note_reports
  for insert to authenticated with check ((select auth.uid()) = reporter);

revoke all on public.shared_note_reports from anon, authenticated;
grant insert (chapter_id, reason) on public.shared_note_reports to authenticated;

create or replace function public.count_shared_note_reports()
returns trigger language plpgsql security definer set search_path = public as $$
declare n int;
begin
  select count(*) into n from public.shared_note_reports where chapter_id = new.chapter_id;
  update public.shared_notes set report_count = n, hidden = (n >= 3) where chapter_id = new.chapter_id;
  return new;
end $$;

drop trigger if exists shared_note_reports_count on public.shared_note_reports;
create trigger shared_note_reports_count after insert on public.shared_note_reports
  for each row execute function public.count_shared_note_reports();

-- ---------- share ----------
create or replace function public.publish_shared_notes(
  p_chapter_id text, p_outline jsonb, p_chunks jsonb, p_model text default null, p_show_name boolean default false)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid          uuid := auth.uid();
  n_total      int;
  n_done       int;
  cur          public.shared_notes%rowtype;
  display_name text;
begin
  if uid is null then
    raise exception 'Sign in to share notes.' using errcode = '28000';
  end if;
  if p_chapter_id is null or p_chapter_id !~ '^c(9|10|11|12)-[a-z0-9-]{3,110}$' then
    raise exception 'Unknown chapter.' using errcode = '22023';
  end if;
  if jsonb_typeof(p_outline) is distinct from 'array' or jsonb_typeof(p_chunks) is distinct from 'array' then
    raise exception 'Notes are not in the expected format.' using errcode = '22023';
  end if;

  n_total := jsonb_array_length(p_outline);
  n_done  := jsonb_array_length(p_chunks);
  if n_total not between 2 and 15 or n_done not between 1 and n_total then
    raise exception 'Notes are not in the expected format.' using errcode = '22023';
  end if;
  if octet_length(p_chunks::text) > 1000000 or octet_length(p_outline::text) > 30000 then
    raise exception 'These notes are too large to share.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_outline) o
             where jsonb_typeof(o -> 'title') is distinct from 'string' or jsonb_typeof(o -> 'topics') is distinct from 'array') then
    raise exception 'Notes are not in the expected format.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_chunks) c
             where jsonb_typeof(c) <> 'string' or char_length(c #>> '{}') not between 300 and 60000) then
    raise exception 'Every part must be complete notes before sharing.' using errcode = '22023';
  end if;

  select * into cur from public.shared_notes where chapter_id = p_chapter_id for update;

  -- Someone else already shared at least as much: keep theirs.
  if cur.chapter_id is not null and cur.contributed_by is distinct from uid
     and not cur.hidden and n_done <= cur.parts_done then
    return jsonb_build_object('status', 'exists', 'parts_done', cur.parts_done, 'parts_total', cur.parts_total);
  end if;

  if p_show_name then
    select nullif(split_part(trim(coalesce(raw_user_meta_data ->> 'full_name', raw_user_meta_data ->> 'name', '')), ' ', 1), '')
      into display_name from auth.users where id = uid;
  end if;

  insert into public.shared_notes as s
    (chapter_id, outline, chunks, parts_done, parts_total, model, contributor_name, contributed_by, updated_at)
  values
    (p_chapter_id, p_outline, p_chunks, n_done, n_total, left(p_model, 60), left(display_name, 40), uid, now())
  on conflict (chapter_id) do update set
    outline          = excluded.outline,
    chunks           = excluded.chunks,
    parts_done       = excluded.parts_done,
    parts_total      = excluded.parts_total,
    model            = excluded.model,
    contributor_name = excluded.contributor_name,
    contributed_by   = excluded.contributed_by,
    updated_at       = now(),
    -- A new sharer replacing a hidden or older copy starts with a clean record.
    hidden           = case when s.contributed_by is distinct from excluded.contributed_by then false else s.hidden end,
    report_count     = case when s.contributed_by is distinct from excluded.contributed_by then 0 else s.report_count end;

  if cur.chapter_id is not null and cur.contributed_by is distinct from uid then
    delete from public.shared_note_reports where chapter_id = p_chapter_id;
  end if;

  return jsonb_build_object('status', 'shared', 'parts_done', n_done, 'parts_total', n_total);
end $$;

-- ---------- my shares / unshare ----------
create or replace function public.my_shared_chapters()
returns table (chapter_id text, parts_done int)
language sql stable security definer set search_path = public as $$
  select s.chapter_id, s.parts_done from public.shared_notes s where s.contributed_by = auth.uid();
$$;

create or replace function public.unshare_notes(p_chapter_id text)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  delete from public.shared_notes where chapter_id = p_chapter_id and contributed_by = auth.uid();
  return found;
end $$;

-- Only signed-in students may call these; nobody calls the trigger function directly.
revoke all on function public.publish_shared_notes(text, jsonb, jsonb, text, boolean) from public, anon;
revoke all on function public.my_shared_chapters() from public, anon;
revoke all on function public.unshare_notes(text) from public, anon;
revoke all on function public.count_shared_note_reports() from public, anon, authenticated;
grant execute on function public.publish_shared_notes(text, jsonb, jsonb, text, boolean) to authenticated;
grant execute on function public.my_shared_chapters() to authenticated;
grant execute on function public.unshare_notes(text) to authenticated;
